                max_length = lengths[neighbor]
                max_node = neighbor
        if max_node != -1:
            dfs(max_node, path)

    visited = set()
    paths = []
    for i in range(n):
        if i not in visited:
            path = []
            dfs(i, path)
            paths.append(path)

    if len(paths) > 1:
        return "AMBIGUOUS"

    path = paths[0][::-1]
    result = ""
    for node in path:
        suffix_len = lengths[node]
        result += fragments[node][suffix_len:]

    return result

