def reconstruct_manuscript(fragments):
    n = len(fragments)
    graph = [[None] * n for _ in range(n)]
    lengths = [[0] * n for _ in range(n)]

    # Build the overlap graph
    for i in range(n):
        for j in range(n):
            if i != j:
                suffix = fragments[i][-5:]
                prefix = fragments[j][:5]
                if suffix == prefix:
                    graph[i][j] = True
                    lengths[i][j] = min(len(suffix), len(prefix))

    # Find all Eulerian paths
    def dfs(v, path):
        for u in range(n):
            if graph[v][u]:
                graph[v][u] = False
                dfs(u, path + [u])
        result.append(path[::-1])

    start_nodes = []
    for v in range(n):
        in_degree = sum(graph[u][v] for u in range(n))
        out_degree = sum(graph[v][u] for u in range(n))
        if in_degree == out_degree == 0:
            continue
        elif in_degree == out_degree == 1:
            if out_degree > 0:
                start_nodes.append(v)
        else:
            return "AMBIGUOUS"

    result = []
    for start in start_nodes:
        dfs(start, [start])

    if len(result) != 1:
        return "AMBIGUOUS"

    path = result[0]
    reconstructed_text = fragments[path[0]]
    for i in range(1, len(path)):
        overlap_length = lengths[path[i-1]][path[i]]
        reconstructed_text += fragments[path[i]][overlap_length:]

    return reconstructed_text

