import sys
from collections import defaultdict

def find_overlapping_pairs(fragments):
    pairs = []
    for i in range(len(fragments)):
        for j in range(len(fragments)):
            if i != j:
                a, b = fragments[i], fragments[j]
                min_len = min(5, len(a), len(b))
                for k in range(min_len, 0, -1):
                    if a[-k:] == b[:k]:
                        pairs.append((i, j, k))
                        break
    return pairs

def build_graph(fragments):
    graph = defaultdict(list)
    for u, v, _ in find_overlapping_pairs(fragments):
        graph[u].append(v)
    return graph

def dfs(node, visited, stack, graph):
    visited[node] = True
    for neighbor in graph[node]:
        if not visited[neighbor]:
            dfs(neighbor, visited, stack, graph)
    stack.insert(0, node)

def topological_sort(graph, n):
    visited = [False] * n
    stack = []
    for node in range(n):
        if not visited[node]:
            dfs(node, visited, stack, graph)
    return stack

def get_reconstruction_order(fragments, graph, n):
    topo_order = topological_sort(graph, n)
    orders = []
    def backtrack(path, remaining):
        if not remaining:
            orders.append(path[:])
            return
        last_fragment = fragments[path[-1]]
        for next_node in remaining:
            if last_fragment[-5:] == fragments[next_node][:5]:
                backtrack(path + [next_node], remaining - {next_node})
    backtrack([topo_order[0]], set(range(1, n)))
    return orders

def reconstruct_text(fragments, orders):
    for order in orders:
        reconstructed = fragments[order[0]]
        for fragment_id in order[1:]:
            suffix_length = 5
            while fragments[fragment_id][:suffix_length] != reconstructed[-suffix_length:]:
                suffix_length -= 1
            reconstructed += fragments[fragment_id][suffix_length:]
        yield reconstructed

def main():
    input = sys.stdin.read
    data = input().splitlines()
    n = int(data[0])
    fragments = data[1:n+1]

    graph = build_graph(fragments)
    orders = get_reconstruction_order(fragments, graph, n)

    if len(orders) == 1:
        print(next(reconstruct_text(fragments, orders)).strip())
    else:
        print("AMBIGUOUS")

if __name__ == "__main__":
    main()
